<script setup>
import { computed,onBeforeUnmount,onMounted,nextTick,ref } from 'vue'
import { api } from './api'
import ContactFieldsPanel from './ContactFieldsPanel.vue'
const conversations=ref([]),messages=ref([]),selectedId=ref(null),reply=ref(''),loading=ref(false),sending=ref(false),error=ref(''),pane=ref(null),detailsOpen=ref(true)
const selected=computed(()=>conversations.value.find(c=>c.id===selectedId.value)||null)
let timer=null,refreshing=false
function name(c){return c?.contact?.name||c?.contact?.username||String(c?.chat_id||'Telegram')}
function time(v){if(!v)return'';return new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit'}).format(new Date(v))}
function formatPhone(v){const raw=String(v||'').trim();if(!raw)return'';const digits=raw.replace(/\D/g,'');if(!digits)return raw;let d=digits;if(d.startsWith('00'))d=d.slice(2);if(d.startsWith('27')&&d.length===11)return `+27 ${d.slice(2,4)} ${d.slice(4,7)} ${d.slice(7)}`;return raw.startsWith('+')?raw:`+${d}`}
function messageBody(m){if(m?.message_type==='contact')return `📱 Contact shared — ${formatPhone(m.body)}`;return m?.body||`[${m?.message_type}]`}
function nearBottom(){const el=pane.value;if(!el)return true;return el.scrollHeight-el.scrollTop-el.clientHeight<100}
async function bottom(){await nextTick();const el=pane.value;if(!el)return;el.scrollTop=el.scrollHeight;requestAnimationFrame(()=>{if(pane.value)pane.value.scrollTop=pane.value.scrollHeight})}
async function loadConversations(){conversations.value=await api.telegramConversations()}
async function load({auto=true}={}){try{await loadConversations();if(auto&&!selectedId.value&&conversations.value.length)await select(conversations.value[0].id)}catch(e){error.value=e.message}}
async function syncMessages(id,{forceBottom=false,markRead=true}={}){const wasNearBottom=nearBottom(),latest=await api.telegramMessages(id);if(Number(id)!==Number(selectedId.value))return false;const oldSignature=messages.value.map(m=>`${m.id}:${m.direction}:${m.message_type}:${m.body||''}`).join('|'),newSignature=latest.map(m=>`${m.id}:${m.direction}:${m.message_type}:${m.body||''}`).join('|'),changed=oldSignature!==newSignature;if(changed)messages.value=[...latest];if(markRead&&latest.some(m=>m.direction==='inbound'))await api.telegramMarkRead(id);if(changed&&(forceBottom||wasNearBottom))await bottom();return changed}
async function select(id){selectedId.value=Number(id);loading.value=true;error.value='';messages.value=[];try{await syncMessages(selectedId.value,{forceBottom:true});await loadConversations();await bottom()}catch(e){error.value=e.message}finally{loading.value=false}}
async function refresh(){if(refreshing)return;refreshing=true;try{await loadConversations();const id=selectedId.value;if(id)await syncMessages(id)}catch(_){ }finally{refreshing=false}}
async function send(){const text=reply.value.trim();if(!selected.value||!text||sending.value)return;sending.value=true;error.value='';try{const id=selected.value.id;await api.telegramSendText(id,text);reply.value='';await syncMessages(id,{forceBottom:true,markRead:false});await loadConversations()}catch(e){error.value=e.message}finally{sending.value=false}}
onMounted(async()=>{await load();timer=setInterval(refresh,3000)});onBeforeUnmount(()=>timer&&clearInterval(timer))
</script>
<template><div class="tg-chat" :class="{'details-closed':!detailsOpen}"><aside class="tg-list"><header><div><p>TELEGRAM</p><h2>Conversations</h2></div><button @click="refresh">↻</button></header><div v-if="!conversations.length" class="empty">No Telegram conversations yet.<small>Send your bot a message and it will appear here.</small></div><button v-for="c in conversations" :key="c.id" class="row" :class="{active:c.id===selectedId,unread:c.unread_count}" @click="select(c.id)"><span class="avatar">{{name(c).slice(0,1).toUpperCase()}}</span><span class="copy"><span><b>{{name(c)}}</b><time>{{time(c.last_message_at)}}</time></span><small>{{c.last_message_direction==='outbound'?'You: ':''}}{{c.last_message_type==='contact'?`📱 Contact shared — ${formatPhone(c.last_message_body)}`:(c.last_message_body||'Telegram message')}}</small><i>@{{c.contact.username||'telegram'}} · {{c.bot.first_name||c.bot.username}}</i></span><em v-if="c.unread_count">{{c.unread_count}}</em></button></aside>
<section class="chat"><template v-if="selected"><header><div class="avatar large">{{name(selected).slice(0,1).toUpperCase()}}</div><div class="identity"><b>{{name(selected)}}</b><span>@{{selected.contact.username||selected.contact.telegram_user_id}} · via @{{selected.bot.username}}</span></div><button class="details-toggle" @click="detailsOpen=!detailsOpen">{{detailsOpen?'Hide details':'Details'}}</button></header><div ref="pane" class="messages"><div v-if="loading" class="loading">Loading…</div><article v-for="m in messages" :key="m.id" :class="m.direction"><div><span v-if="m.message_type!=='text'" class="type">{{m.message_type}}</span><p>{{messageBody(m)}}</p><time>{{time(m.telegram_timestamp||m.created_at)}}</time></div></article></div><form class="composer" @submit.prevent="send"><textarea v-model="reply" rows="2" placeholder="Reply on Telegram…" @keydown.enter.exact.prevent="send"></textarea><button :disabled="sending||!reply.trim()">{{sending?'Sending…':'Send'}}</button></form></template><div v-else class="no-chat"><div>T</div><h2>Telegram Live Chat</h2><p>Send your connected bot a message to start the first conversation.</p></div><p v-if="error" class="error">{{error}}</p></section>
<aside v-if="detailsOpen" class="customer-panel"><template v-if="selected"><div class="customer-head"><span class="avatar profile-avatar">{{name(selected).slice(0,1).toUpperCase()}}</span><div><p>CUSTOMER SNAPSHOT</p><h3>{{name(selected)}}</h3><span>@{{selected.contact.username||'no_username'}}</span></div></div><dl class="snapshot"><div><dt>Telegram ID</dt><dd>{{selected.contact.telegram_user_id}}</dd></div><div><dt>Channel</dt><dd>Telegram</dd></div><div><dt>Bot</dt><dd>@{{selected.bot.username||selected.bot.first_name}}</dd></div><div><dt>Status</dt><dd>{{selected.status}}</dd></div></dl><ContactFieldsPanel :contact="selected.contact" channel="telegram" compact /></template><div v-else class="panel-empty">Select a conversation.</div></aside></div></template>
<style scoped>
