dentity{flex:1}.chat header b,.chat header span{display:block}.chat header span{margin-top:3px;color:#809188;font-size:11px}.details-toggle{border:1px solid #d7e1dc;background:#fff;border-radius:8px;padding:7px 10px;cursor:pointer}.messages{flex:1 1 0;min-height:0;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;padding:22px;background:#f5f8f7;scroll-behavior:smooth}.messages article{display:flex;margin:7px 0}.messages article.inbound{justify-content:flex-start}.messages article.outbound{justify-content:flex-end}.messages article>div{max-width:70%;padding:9px 11px;border-radius:11px;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.05)}.messages article.outbound>div{background:#dff5eb}.messages p{margin:0;white-space:pre-wrap;line-height:1.45}.messages time{display:block;text-align:right;margin-top:4px;color:#87968f;font-size:9px}.type{display:inline-block;margin-bottom:5px;padding:2px 5px;border-radius:4px;background:#e6f3f9;color:#147ca9;font-size:8px;font-weight:800;text-transform:uppercase}.composer{flex:0 0 auto;display:flex;gap:10px;padding:13px;border-top:1px solid #e0e8e4;background:#fff}.composer textarea{flex:1;resize:none;border:1px solid #cfddd7;border-radius:9px;padding:10px;font:inherit}.composer button{align-self:stretch;border:0;border-radius:9px;background:#229ed9;color:#fff;padding:0 20px;font-weight:800;cursor:pointer}.composer button:disabled{opacity:.5}.customer-panel{min-width:0;overflow:auto;border-left:1px solid #e1e9e5;background:#fbfdfc;padding:16px}.customer-head{display:flex;gap:10px;align-items:center;padding-bottom:14px;border-bottom:1px solid #e5ece8}.customer-head p{margin:0;color:#229ed9;font-size:8px;font-weight:900;letter-spacing:.08em}.customer-head h3{margin:3px 0 1px}.customer-head span{color:#7d8d85;font-size:10px}.profile-avatar{background:#229ed9;color:#fff}.snapshot{margin:10px 0 14px}.snapshot div{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid #edf1ef}.snapshot dt{font-size:10px;color:#7a8b83}.snapshot dd{margin:0;font-size:10px;font-weight:700;text-align:right}.customer-panel :deep(.contact-section){background:#fff;border:1px solid #e0e8e4;border-radius:10px;padding:12px}.customer-panel :deep(.section-title){display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.customer-panel :deep(.section-title h3),.customer-panel :deep(.section-title p){margin:0}.customer-panel :deep(.section-title p){color:#229ed9;font-size:8px;font-weight:900}.customer-panel :deep(.section-title span){font-size:9px;color:#71827a}.panel-empty{padding:40px 10px;text-align:center;color:#7a8b83}.no-chat{margin:auto;text-align:center;color:#74867e}.no-chat div{width:54px;height:54px;margin:auto;border-radius:16px;background:#229ed9;color:#fff;display:grid;place-items:center;font-size:23px;font-weight:900}.no-chat h2{color:#173026}.error{position:absolute;left:15px;right:15px;bottom:15px;background:#fff0f0;color:#992d2d;padding:9px;border-radius:7px}@media(max-width:1100px){.tg-chat{grid-template-columns:280px minmax(0,1fr)}.customer-panel{position:absolute;right:0;top:0;bottom:0;width:320px;z-index:20;box-shadow:-10px 0 25px rgba(0,0,0,.08)}}@media(max-width:800px){.tg-chat{grid-template-columns:1fr;grid-template-rows:auto minmax(520px,1fr);height:auto}.tg-list{max-height:300px;border-right:0;border-bottom:1px solid #e2e9e6}.chat{min-height:520px;height:520px}}
</style>